if ($_SERVER['REQUEST_METHOD'] === 'POST') { if (!$csrf->valid($_POST['_csrf_token'] ?? null)) { $error = 'Your form session expired. Refresh and try again.'; } elseif ((int) ($_POST['fisherman_id'] ?? 0) < 1 || (int) ($_POST['species_id'] ?? 0) < 1 || (float) ($_POST['quantity'] ?? 0) <= 0) { $error = 'Fisherman, species, and quantity are required.'; } else { try { $service->addFishCatch($_POST); $message = 'Fishery monitoring record saved.'; } catch (Throwable $exception) { error_log($exception->getMessage()); $error = 'Unable to save the fishery record.'; } } }
