?>
<main class="min-h-screen bg-surface-container-low"><section class="max-w-container-max mx-auto px-gutter-mobile lg:px-gutter-desktop py-space-xl"><p class="text-xs uppercase tracking-wider text-primary font-bold">Data entry and monitoring</p><h1 class="text-3xl font-extrabold mt-2">Fishery catch monitoring</h1><p class="text-sm text-on-surface-variant mt-2 mb-space-lg">Record landing activity, catch volume, species, and estimated value.</p><?php if ($message): ?><div class="mb-4 rounded-lg border border-primary bg-primary/10 px-4 py-3 text-sm text-primary"><?= htmlspecialchars($message) ?></div><?php endif; ?><?php if ($error): ?><div class="mb-4 rounded-lg border border-error bg-error/10 px-4 py-3 text-sm text-error"><?= htmlspecialchars($error) ?></div><?php endif; ?><div class="grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)] gap-space-lg"><form method="post" class="bg-surface-container-lowest border border-surface-container rounded-lg p-space-lg space-y-4"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($csrf->token()) ?>"><h2 class="text-xl font-bold">Record fish catch</h2><div class="grid grid-cols-2 gap-3"><select name="fisherman_id" required class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><option value="">Fisherman</option><?php foreach ($fishermen as $item): ?><option value="<?= (int) $item['id'] ?>"><?= htmlspecialchars($item['last_name'] . ', ' . $item['first_name']) ?></option><?php endforeach; ?></select><select name="species_id" required class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><option value="">Species</option><?php foreach ($species as $item): ?><option value="<?= (int) $item['id'] ?>"><?= htmlspecialchars($item['common_name']) ?></option><?php endforeach; ?></select></div><div class="grid grid-cols-2 gap-3"><select name="boat_id" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><option value="">Boat (optional)</option><?php foreach ($boats as $item): ?><option value="<?= (int) $item['id'] ?>"><?= htmlspecialchars($item['name'] ?: $item['registration_number']) ?></option><?php endforeach; ?></select><select name="gear_id" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><option value="">Gear (optional)</option><?php foreach ($gears as $item): ?><option value="<?= (int) $item['id'] ?>"><?= htmlspecialchars($item['name']) ?></option><?php endforeach; ?></select></div><div class="grid grid-cols-2 gap-3"><input name="catch_date" type="date" required value="<?= date('Y-m-d') ?>" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><input name="landing_site" placeholder="Landing site" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"></div><div class="grid grid-cols-3 gap-3"><input name="quantity" type="number" min="0.01" step="0.01" required placeholder="Quantity" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><input name="unit" value="kg" placeholder="Unit" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><input name="estimated_value" type="number" min="0" step="0.01" placeholder="Value" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"></div><textarea name="notes" placeholder="Notes" class="form-input-custom w-full rounded-lg p-3 text-sm border border-outline-variant"></textarea><button class="rounded-lg bg-primary text-on-primary px-4 py-3 font-bold text-sm" type="submit">Save catch record</button></form><div class="bg-surface-container-lowest border border-surface-container rounded-lg overflow-hidden"><div class="p-space-lg border-b border-surface-container"><h2 class="text-xl font-bold">Recent catch records</h2></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-surface-container-low text-xs uppercase"><tr><th class="p-3">Date</th><th class="p-3">Fisherman ID</th><th class="p-3">Species ID</th><th class="p-3">Quantity</th></tr></thead><tbody><?php foreach ($catches as $item): ?><tr class="border-t border-surface-container"><td class="p-3"><?= htmlspecialchars($item['catch_date']) ?></td><td class="p-3"><?= (int) $item['fisherman_id'] ?></td><td class="p-3"><?= (int) $item['species_id'] ?></td><td class="p-3 font-semibold"><?= htmlspecialchars($item['quantity'] . ' ' . $item['unit']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></section></main><?php require_once __DIR__ . '/../frontend/components/footer.php'; ?>
